import type { DesignDNA } from '../schema/dna';
import type { SfxKind } from '../timing/types';

/** Royalty-free library bundled in /public/audio (generated by scripts/audio/make_audio.py). */
export const MUSIC = [
  { id: 'warm-pluck', title: 'دافئ', bpm: 100, moods: ['soft-ui', 'playful'], energy: 0.4 },
  { id: 'tech-pulse', title: 'تقني', bpm: 122, moods: ['mechanical', 'cinematic'], energy: 0.8 },
  { id: 'upbeat-pop', title: 'حماسي', bpm: 118, moods: ['punchy', 'playful'], energy: 0.9 },
  { id: 'calm-pad', title: 'هادئ', bpm: 80, moods: ['soft-ui', 'cinematic'], energy: 0.2 },
] as const;

export const publicUrl = (path: string) => {
  const base = typeof import.meta !== 'undefined' && import.meta.env ? import.meta.env.BASE_URL : './';
  return `${base}${path.replace(/^\//, '')}`;
};

/** auto music: match the DNA's sfx palette / energy */
export const pickMusic = (dna: DesignDNA, trackId: string): string | null => {
  if (trackId === 'none') return null;
  if (trackId !== 'auto' && trackId !== 'upload') return MUSIC.some((m) => m.id === trackId) ? publicUrl(`audio/music/${trackId}.mp3`) : null;
  if (trackId === 'upload') return null;
  const cands = MUSIC.filter((m) => (m.moods as readonly string[]).includes(dna.sfxPalette));
  const list = cands.length ? cands : MUSIC;
  return publicUrl(`audio/music/${list[dna.seed % list.length]!.id}.mp3`);
};

export const sfxSrc = (kind: SfxKind, palette: DesignDNA['sfxPalette']): string | null => {
  const hard = palette === 'punchy' || palette === 'mechanical' || palette === 'cinematic';
  const file: Record<SfxKind, string> = {
    whoosh: hard ? 'whoosh-hard' : 'whoosh-soft',
    swipe: 'swipe',
    pop: palette === 'mechanical' ? 'mech-clunk' : hard ? 'pop-punchy' : 'pop-soft',
    tick: 'tick',
    impact: palette === 'soft-ui' ? 'pop-punchy' : 'impact',
    riser: 'riser',
    ding: 'ding',
    click: 'click',
  };
  return publicUrl(`audio/sfx/${file[kind]}.mp3`);
};
